import { readFile } from "node:fs/promises";
import path from "node:path";
import { certificates } from "@/lib/content";
import { verifyCertificate } from "@/lib/server/cert-token";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Serves a certificate presentation copy: reduced resolution, personal details blurred, ownership watermark baked in.
 * Copies live in /private (never in /public) and are generated by scripts/prepare-certificates.mjs from originals
 * that never enter the repository. Requests need a short-lived signed token minted by the vault page.
 */
export async function GET(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const cert = certificates.find((c) => c.id === id);
  const token = new URL(req.url).searchParams.get("t");
  if (!cert || !verifyCertificate(id, token)) return new Response("Not found", { status: 404 });
  // Deter embedding on other sites: browsers send Sec-Fetch-Site on image requests.
  const site = req.headers.get("sec-fetch-site");
  if (site && site !== "same-origin" && site !== "none") return new Response("Not found", { status: 404 });
  try {
    const file = await readFile(path.join(process.cwd(), "private", "certificates", `${cert.id}.jpg`));
    return new Response(new Uint8Array(file), {
      headers: {
        "content-type": "image/jpeg",
        "content-disposition": "inline",
        "cache-control": "private, no-store",
        "cross-origin-resource-policy": "same-origin",
        "x-robots-tag": "noindex, noimageindex",
      },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
